// Packaged responsive long-content and trusted keyboard/touch evidence (#619).
// Audit mode only, on its own target after the ordinary audit. The SPA, CSP, assets and client
// validation are the real packaged JVM responses; `/nested/api/v1/*` reads are fulfilled in DevTools
// from the #619 `responsive` scenario generated by frontend/dev/generate-fixtures.py (schema- and
// semantics-validated by the generator itself). The dev server is not imported or started.
// Sizes are CDP Emulation device metrics (CSS viewport + device scale factor). They are NOT Chrome
// HostZoomMap browser zoom; earlier local real-zoom evidence is separate (build/orchestration/responsive-619-*).
// Touch is CDP-emulated (Emulation.setTouchEmulationEnabled + Input.dispatchTouchEvent), not a physical device.
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { constants as fsConstants, promises as fs, readFileSync } from 'node:fs';
import { join } from 'node:path';

export const RESPONSIVE_SCHEMA = 'packaged-responsive-audit/v2';
export const RESPONSIVE_SIZING = 'cdp-Emulation.setDeviceMetricsOverride (CSS viewport + deviceScaleFactor); not Chrome HostZoomMap browser zoom';
export const RESPONSIVE_TOUCH = 'cdp-Emulation.setTouchEmulationEnabled + Input.dispatchTouchEvent; browser-emulated, not a physical device';
export const MAX_RESPONSIVE_PNG_BYTES = 2 * 1024 * 1024;
export const MAX_TABS = 120;
const TEXT_CAP = 160;
const cap = (value) => typeof value === 'string' ? value.slice(0, TEXT_CAP) : value;
const sha256 = (bytes) => createHash('sha256').update(bytes).digest('hex');
const HEX64 = /^[0-9a-f]{64}$/;

// Identities pinned against frontend/dev/generate-fixtures.py by the pure controls.
export const RESPONSIVE_JOB = 'f619f619f619f619f619f619f619f619';
export const RESPONSIVE_RUN = 'fixture_run_responsive';
export const RESPONSIVE_REVISION = 'fixture_revision_responsive';
export const RESPONSIVE_HEX_FILE = `file_1_${'2'.repeat(64)}`;
export const RESPONSIVE_EXPLORATION = Object.freeze(['partial', 'preparation']);
const J = `/nested/jobs/${RESPONSIVE_JOB}`;
const R = `${J}/runs/${RESPONSIVE_RUN}`;
/** Product copy the gate requires verbatim (pinned to frontend/src/copy by the controls; never invented here). */
export const PRODUCT_COPY = Object.freeze({
  // explorationCasesCopy.unavailable: the CaseReader alert for a refused artifact read (status 200 carries no reference ID).
  caseRefusal: 'Case details are unavailable or exceed this viewer’s format or limits. Refresh the report or download its observed JSON.',
  // recordedValidationCopy titles of the four byte-preview <details> summaries.
  previewTitles: Object.freeze(['Original standard output', 'Rebuilt standard output', 'Original standard error', 'Rebuilt standard error']),
});
/** Per-phase read bounds: any repeated path beyond this, or more reads in one phase, is a retry storm. */
export const MAX_SAME_PATH_READS = 2;
export const MAX_PHASE_READS = 24;
const LEDGER_CAP = 64;
/** Whole-run request record cap: entries beyond it are counted as dropped and fail the gate (never silently lost). */
export const MAX_RUN_REQUESTS = 4096;

/** Narrow profiles reuse the ordinary audit's sizes; desktop is only for the preferences disclosure. */
export const RESPONSIVE_PROFILES = Object.freeze([
  Object.freeze({ key: 'desktop', name: 'desktop 1440x900', width: 1440, height: 900, deviceScaleFactor: 1, mobile: false, narrow: false }),
  Object.freeze({ key: 'narrow', name: 'narrow 390x844', width: 390, height: 844, deviceScaleFactor: 1, mobile: true, narrow: true }),
  Object.freeze({ key: 'reflow320', name: 'reflow 320', width: 320, height: 640, deviceScaleFactor: 1, mobile: true, narrow: true }),
  Object.freeze({ key: 'scale200', name: 'zoom 200% of 1280x800', width: 640, height: 400, deviceScaleFactor: 2, mobile: false, narrow: true }),
  Object.freeze({ key: 'scale400', name: 'zoom 400% of 1280x800', width: 320, height: 200, deviceScaleFactor: 4, mobile: false, narrow: true }),
]);

/**
 * Named regions. `scroll` regions must overflow and scroll by trusted ArrowRight and touch drag with the page fixed.
 * `reflow` regions are designed to wrap (app.css .source-row pre: pre-wrap/anywhere): no overflow, every row inside,
 * the complete requested content rendered, and trusted keys/drag must move neither the region nor the page.
 */
export const RESPONSIVE_REGIONS = Object.freeze([
  Object.freeze({ key: 'exploration-partial', path: `${J}/runs/${RESPONSIVE_RUN}_partial/evidence`, steps: ['Read exploration evidence', 'Read retained case details'],
    region: 'Retained candidate records', tap: 'Inspect case ', artifact: 'partial', mode: 'scroll' }),
  Object.freeze({ key: 'exploration-preparation', path: `${J}/runs/${RESPONSIVE_RUN}_preparation/evidence`, steps: ['Read exploration evidence', 'Read retained case details'],
    region: 'Retained candidate records', tap: 'Inspect case ', artifact: 'preparation', mode: 'scroll' }),
  Object.freeze({ key: 'validation-bytes', path: `${R}/evidence`, steps: ['Read validation evidence', 'Inspect cases: '],
    region: 'Recorded validation cases', bytePreview: true, mode: 'scroll' }),
  Object.freeze({ key: 'source-hex', path: `${R}/revisions/${RESPONSIVE_REVISION}/source-files/${RESPONSIVE_HEX_FILE}`, steps: ['Open source preview'],
    region: 'Source range content', hexRows: true, mode: 'reflow' }),
]);
export const NAVIGATION_PAGE = Object.freeze({ path: J, routeLink: '/nested/upload', routeHeading: 'Upload a binary' });
export const PREFERENCES = Object.freeze({ trigger: '[aria-controls="display-preferences-panel"]', panel: 'display-preferences-panel', label: 'Display preferences' });

/** The fixed observation matrix the gate requires; never derived from the report. */
export function expectedObservations() {
  const out = [];
  for (const profile of RESPONSIVE_PROFILES) {
    out.push({ profile: profile.key, kind: 'preferences', subject: 'disclosure' });
    if (!profile.narrow) continue;
    out.push({ profile: profile.key, kind: 'navigation', subject: 'disclosure' });
    for (const region of RESPONSIVE_REGIONS) out.push({ profile: profile.key, kind: 'region', subject: region.key });
  }
  return out;
}
export const screenshotName = (o) => `responsive-${o.profile}-${o.kind}-${o.subject}.png`;
const FIXED_NAMES = new Set(expectedObservations().map(screenshotName));
const LONG_NAME_CLASSES = Object.freeze({ hebrew: /[֐-׿]/u, arabic: /[؀-ۿ]/u, cjk: /[一-鿿]/u, emoji: /\p{Extended_Pictographic}/u, combining: /\p{M}/u });

/**
 * Generates the #619 fixture set with the repository generator (pinned python with fastjsonschema),
 * replaces only the bootstrap with the packaged build identity, and returns a bounded responder.
 */
export function responsiveFixtures({ repo, python, buildId, basePath = '/nested/', run = execFileSync }) {
  const generator = join(repo, 'frontend/dev/generate-fixtures.py');
  const generatorSha256 = sha256(readFileSync(generator));
  const output = run(python, ['-B', generator, '--base-path', basePath], { encoding: 'utf8', maxBuffer: 8 * 1024 * 1024 });
  return bindResponsiveFixtures(JSON.parse(output), { buildId, generatorSha256, outputSha256: sha256(output), basePath });
}

/** Pure: generator output -> fixture identities and a responder. Throws when the scenario changed shape. */
export function bindResponsiveFixtures(generated, { buildId, generatorSha256, outputSha256, basePath = '/nested/' }) {
  const api = `${basePath}api/v1`;
  const scenario = (generated?.scenarios ?? []).find((value) => value?.name === 'responsive');
  if (!scenario || scenario.jobPath !== `${api}/jobs/${RESPONSIVE_JOB}` || scenario.runPath !== `${api}/jobs/${RESPONSIVE_JOB}/runs/${RESPONSIVE_RUN}`)
    throw new Error('Generated fixtures lack the #619 responsive scenario at its pinned identity');
  const routes = new Map(Object.entries(generated.routes ?? {}).filter(([path]) => path.startsWith(scenario.jobPath + '/') || path === scenario.jobPath));
  const bootstrap = structuredClone(generated.routes?.[`${api}/bootstrap`]);
  if (!bootstrap?.data) throw new Error('Generated fixtures lack bootstrap');
  Object.assign(bootstrap.data, { basePath, uiBuildId: buildId, sessionExpiresAt: new Date(Date.now() + 3_600_000).toISOString() });
  routes.set(`${api}/bootstrap`, bootstrap);
  for (const shared of ['/jobs', '/recovery']) if (generated.routes?.[api + shared]) routes.set(api + shared, generated.routes[api + shared]);
  const artifacts = new Map();
  for (const kind of RESPONSIVE_EXPLORATION) {
    const runPath = scenario.explorationRunPaths?.[kind];
    const report = generated.routes?.[`${runPath}/reports/exploration`];
    const source = report?.data?.sourceArtifact;
    const content = generated.artifactContents?.[source?.contentHref];
    if (!content || typeof content.body !== 'string') throw new Error(`Generated ${kind} exploration artifact is missing`);
    const bytes = Buffer.from(content.body, 'utf8');
    if (String(bytes.length) !== source.sizeBytes || sha256(bytes) !== source.sha256 || content.sha256 !== source.sha256)
      throw new Error(`Generated ${kind} exploration artifact does not match its report binding`);
    artifacts.set(source.contentHref, { kind, bytes, sha256: source.sha256, sizeBytes: bytes.length, artifactId: source.artifactId });
  }
  const job = routes.get(scenario.jobPath)?.data;
  // The requested hex chunk: its exact bytes define the rows the source preview must render in full.
  const chunkPrefix = `${scenario.runPath}/revisions/${RESPONSIVE_REVISION}/source-files/${RESPONSIVE_HEX_FILE}/chunk?`;
  const chunks = [...routes].filter(([path]) => path.startsWith(chunkPrefix));
  const chunk = chunks.length === 1 ? chunks[0][1]?.data : null;
  if (!chunk || chunk.representation !== 'hex' || typeof chunk.text !== 'string' || !/^(?:[0-9a-f]{2})+$/.test(chunk.text))
    throw new Error('Generated fixtures lack the #619 hex source chunk');
  const hexRows = hexDisplayRows(chunk.text);
  const identity = {
    generator: 'frontend/dev/generate-fixtures.py', generatorSha256, outputSha256, schemaSha256: generated.schemaSha256 ?? null,
    jobId: job?.jobId ?? null, runId: RESPONSIVE_RUN, revisionId: RESPONSIVE_REVISION,
    explorationRuns: RESPONSIVE_EXPLORATION.map((kind) => scenario.explorationRunPaths[kind].split('/').at(-1)),
    longName: job?.displayFilename ?? null,
    hex: { chunkPath: chunks[0][0], hexChars: chunk.text.length, rows: hexRows.length, textSha256: sha256(hexRows.join('\n')) },
    artifacts: [...artifacts.values()].map(({ kind, artifactId, sizeBytes, sha256: digest }) => ({ kind, artifactId, sizeBytes, sha256: digest })),
    artifactPaths: Object.fromEntries([...artifacts].map(([path, value]) => [value.kind, path])),
    routeCount: routes.size,
  };
  const tamper = { path: null };
  const error = (status, code) => ({ status, document: { apiVersion: 1, kind: 'error', requestId: `request_responsive_${status}`,
    error: { code, message: 'Responsive audit fixture response.', retryable: false, details: [], retryAfterMs: null } } });
  return {
    identity, artifacts, tamper,
    /** method, pathname+search (no origin), accept -> response. Unknown reads are 404 and reported as unmapped. */
    respond(method, path, accept = '') {
      if (method !== 'GET' && method !== 'HEAD') return error(405, 'METHOD_NOT_ALLOWED');
      const [pathname, search = ''] = path.split(/(?=\?)/);
      const artifact = !search && artifacts.get(pathname);
      if (artifact) {
        let bytes = artifact.bytes;
        // Real-client digest control: one deliberately altered byte must be rejected by the SPA.
        if (tamper.path === pathname) { bytes = Buffer.from(bytes); bytes[bytes.length - 2] ^= 0x01; }
        return { status: 200, bytes, contentType: 'application/octet-stream', headers: { ETag: `"${artifact.sha256}"` }, artifact: { kind: artifact.kind, servedSha256: sha256(bytes), servedBytes: bytes.length } };
      }
      // Same rules as the development fixture server: exact query, else query-free path; other queries are 400.
      const exact = search ? routes.get(path) : undefined;
      const document = exact ?? routes.get(pathname);
      if (document?.kind === 'events' && !search && accept.includes('text/event-stream')) return error(406, 'STREAM_UNSUPPORTED');
      if (search && !exact && !(document?.kind === 'events' && search === '?transport=poll')) return error(400, 'VALIDATION_FAILED');
      return document ? { status: 200, document } : error(404, 'NOT_FOUND');
    },
  };
}

/** Expected display rows for a hex chunk: 16 bytes per row as space-separated pairs (from the exact chunk bytes). */
export function hexDisplayRows(hex) {
  const rows = [];
  for (let index = 0; index < hex.length; index += 32) rows.push(hex.slice(index, index + 32).match(/../g).join(' '));
  return rows;
}

// Capture-phase recorder for trusted input; reinstalled after each navigation.
export const INPUT_RECORDER = `(() => {
  if (window.__responsiveInput) return true;
  const log = []; Object.defineProperty(window, '__responsiveInput', { value: log, configurable: true });
  const describe = t => t && t.tagName ? t.tagName.toLowerCase() + (t.getAttribute('aria-label') ? '[' + t.getAttribute('aria-label').slice(0, 40) + ']' : '') : null;
  for (const type of ['keydown', 'pointerdown', 'pointerup', 'touchstart', 'touchend', 'click'])
    addEventListener(type, e => { if (log.length < 400) log.push({ type, trusted: e.isTrusted, key: e.key ?? null, pointerType: e.pointerType ?? null, target: describe(e.target) }); }, true);
  return true;
})()`;
export const FOCUS = `(() => { const e = document.activeElement; if (!e || e === document.body) return null;
  return { tag: e.tagName.toLowerCase(), name: (e.getAttribute('aria-label') || e.textContent || '').trim().slice(0, 80), focusVisible: e.matches(':focus-visible'),
    inNavigation: !!e.closest('#main-navigation-links'), inPreferences: !!e.closest('#${PREFERENCES.panel}'), heading: e.matches('main h1'),
    toggle: e.matches('.navigation-toggle'), trigger: e.matches('${PREFERENCES.trigger}'), href: e.getAttribute('href') }; })()`;
const PAGE = `({ scrollX, scrollY, overflow: document.scrollingElement.scrollWidth - document.scrollingElement.clientWidth,
  innerWidth, innerHeight, devicePixelRatio, path: location.pathname, h1: (document.querySelector('main h1')?.textContent ?? '').trim().slice(0, 80) })`;
/** Selector expressions shared by the driver and the real-component jsdom control (frontend/tests/packaged-responsive-fixtures.test.tsx). */
export const regionExpr = (name) => `[...document.querySelectorAll('[role="region"][tabindex="0"]')].find(e => e.getAttribute('aria-label') === ${JSON.stringify(name)} && e.checkVisibility())`;
export const byLabel = (prefix) => `[...document.querySelectorAll('main button')].find(e => !e.disabled && (e.getAttribute('aria-label') || e.textContent).trim().startsWith(${JSON.stringify(prefix)}))`;
/** The first byte-preview disclosure summary inside the region; activated by trusted input before any measurement. */
export const summaryExpr = (sel) => `(${sel})?.querySelector('details > summary')`;
/** Byte-preview state after activation: the summary's details must be open and its previews visible at their 16rem minimum. */
export const bytePreviewExpr = (sel) => `(() => { const e = ${sel}; const s = e?.querySelector('details > summary'); const d = s?.parentElement;
  const rem = parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
  const shown = d ? [...d.querySelectorAll('pre.byte-preview')].filter(p => p.checkVisibility()) : [];
  return { summary: (s?.textContent ?? '').trim().slice(0, 80), open: d?.open === true, total: e ? e.querySelectorAll('pre.byte-preview').length : 0,
    visible: shown.length, minWidth: shown.length ? Math.min(...shown.map(p => p.getBoundingClientRect().width)) : 0, rem }; })()`;
/** Reflowed source rows: the exact rendered row text plus whether each row box lies inside the region box. */
export const hexRowsExpr = (sel) => `(() => { const e = ${sel}; const r = e.getBoundingClientRect();
  const rows = [...e.querySelectorAll('.source-row pre')];
  return { scrollWidth: e.scrollWidth, clientWidth: e.clientWidth, rows: rows.length, text: rows.map(p => p.textContent).join('\\n'),
    inside: rows.filter(p => { const q = p.getBoundingClientRect(); return q.left >= r.left - 1 && q.right <= r.right + 1; }).length }; })()`;

const KEYS = { Tab: ['Tab', 'Tab', 9], Enter: ['Enter', 'Enter', 13, '\r'], Escape: ['Escape', 'Escape', 27], ArrowRight: ['ArrowRight', 'ArrowRight', 39] };
const LIMITS = Object.freeze([RESPONSIVE_SIZING, RESPONSIVE_TOUCH,
  'Start points are programmatic main-heading focus and programmatic scrollLeft=0/scrollIntoView resets; every measured action is trusted CDP input.',
  'Source range content is a reflow region by product design (pre-wrap rows); it is checked for complete wrapped content, not 2-D scrolling.',
  'Display preferences is a disclosure (button + aria-expanded + hidden panel), not a modal dialog; no focus trap is claimed.',
  'Not screen-reader (#617), browser-menu/HostZoomMap zoom or physical-device evidence.']);

export function createResponsiveSection() {
  return { schema: RESPONSIVE_SCHEMA, sizing: RESPONSIVE_SIZING, touch: RESPONSIVE_TOUCH, fixtures: null, digestControl: null,
    observations: [], unmapped: [], fulfillFailures: [], restored: null, limits: [...LIMITS] };
}

/**
 * Pure: element rect (viewport CSS px, possibly fractional) -> the enclosing whole-CSS-pixel page clip intersected
 * with the viewport, or null when nothing of the element is visible. The scroll offset and viewport must be integral
 * so the snapped clip stays inside the viewport; non-finite or negative geometry is rejected rather than guessed.
 */
export function snapClip(r, v) {
  const num = (...values) => values.every((value) => typeof value === 'number' && Number.isFinite(value));
  if (!r || !v || !num(r.left, r.top, r.width, r.height) || r.width < 0 || r.height < 0) throw new Error('invalid element rect');
  if (![v.scrollX, v.scrollY, v.innerWidth, v.innerHeight].every(Number.isInteger) || v.innerWidth < 1 || v.innerHeight < 1)
    throw new Error('viewport scroll offset or size is not integral CSS pixels');
  const x0 = Math.max(Math.floor(r.left + v.scrollX), v.scrollX); const y0 = Math.max(Math.floor(r.top + v.scrollY), v.scrollY);
  const x1 = Math.min(Math.ceil(r.left + r.width + v.scrollX), v.scrollX + v.innerWidth);
  const y1 = Math.min(Math.ceil(r.top + r.height + v.scrollY), v.scrollY + v.innerHeight);
  return x1 - x0 >= 1 && y1 - y0 >= 1 ? { x: x0, y: y0, width: x1 - x0, height: y1 - y0, scale: 1 } : null;
}

/** Bounded per-phase request ledger: [{ method, path, status, count }] with totals. */
function ledgerSummary(entries) {
  const byKey = new Map();
  for (const e of entries) {
    const key = `${e.method} ${e.path} ${e.status}`;
    const value = byKey.get(key) ?? { method: e.method, path: String(e.path).slice(0, 512), status: e.status, count: 0 };
    value.count++; byKey.set(key, value);
  }
  const rows = [...byKey.values()];
  return { reads: entries.filter((e) => e.method === 'GET' || e.method === 'HEAD').length, mutations: entries.filter((e) => e.method !== 'GET' && e.method !== 'HEAD').length,
    failed: entries.filter((e) => e.status >= 400 || e.unmapped).length, truncated: rows.length > LEDGER_CAP, paths: rows.slice(0, LEDGER_CAP) };
}

const emulateProfile = async (profile, call) => {
  await call('Emulation.setDeviceMetricsOverride', { width: profile.width, height: profile.height, deviceScaleFactor: profile.deviceScaleFactor, mobile: profile.mobile });
  await call('Emulation.setTouchEmulationEnabled', { enabled: profile.narrow, maxTouchPoints: profile.narrow ? 5 : 1 });
};
const emulateControl = (call) => call('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });

/**
 * Drives the matrix; appends each observation as built; records failure and restores state without masking errors.
 * The defaults are the v2 emulation audit. The real-zoom section (packaged-browser-real-zoom.mjs) passes its own
 * profiles, a sizer that only enables labelled touch emulation and observes size, a per-navigation probe, and
 * restoreMetrics:false so no device-metrics method is ever sent on a zoomed target.
 */
export async function qualifyResponsive({ cdp, makeTarget, evaluate, ready, delay, root, origin, fixtures, section = createResponsiveSection(),
  profiles = RESPONSIVE_PROFILES, sizing = RESPONSIVE_SIZING, sizeProfile = emulateProfile, sizeControl = emulateControl, afterNavigate = null, restoreMetrics = true }) {
  let target = null; let failed = false; let fetchHandler = null;
  const call = (method, params = {}) => cdp.call(method, params, target.sessionId);
  const served = [];
  const requests = [];
  let dropped = 0;
  // Every in-flight Fetch.fulfillRequest; each is bounded by the DevTools per-call deadline, so a snapshot settles.
  const pending = new Set();
  const settleFulfilments = async () => { if (pending.size) await Promise.allSettled([...pending]); };
  const press = async (name, modifiers = 0) => {
    const [key, code, vk, text] = KEYS[name];
    await call('Input.dispatchKeyEvent', { type: text ? 'keyDown' : 'rawKeyDown', key, code, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk, modifiers, ...(text ? { text } : {}) });
    await call('Input.dispatchKeyEvent', { type: 'keyUp', key, code, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk, modifiers });
  };
  const rect = (expr) => evaluate(target, `(() => { const e = ${expr}; if (!e) return null; const r = e.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2, left: r.left, top: r.top, width: r.width, height: r.height, docLeft: r.left + scrollX, docTop: r.top + scrollY }; })()`);
  const tap = async (point) => {
    await call('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: point.x, y: point.y }] });
    await call('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  };
  const click = async (point) => {
    await call('Input.dispatchMouseEvent', { type: 'mousePressed', x: point.x, y: point.y, button: 'left', clickCount: 1 });
    await call('Input.dispatchMouseEvent', { type: 'mouseReleased', x: point.x, y: point.y, button: 'left', clickCount: 1 });
  };
  const visible = (expr) => `(() => { const e = ${expr}; if (!e) return false; e.scrollIntoView({ block: 'center', inline: 'nearest' }); return true; })()`;
  const navigate = async (path, label) => {
    await call('Page.navigate', { url: origin + path });
    await ready(target, `document.querySelector('main h1') !== null && document.querySelector('main [aria-busy="true"]') === null`, label);
    await evaluate(target, INPUT_RECORDER);
    if (afterNavigate) await afterNavigate(target, label);
  };
  const input = () => evaluate(target, 'window.__responsiveInput.splice(0)');
  // Forward first where the target follows main h1 in DOM order (regions); backward first for header controls.
  const tabUntil = async (predicate, label, first = 'backward') => {
    for (const shift of first === 'forward' ? [false, true] : [true, false]) {
      await evaluate(target, `document.querySelector('main h1').focus()`);
      for (let count = 1; count <= MAX_TABS; count++) {
        await press('Tab', shift ? 8 : 0);
        if (await evaluate(target, `(() => { const f = ${FOCUS}; return !!f && (${predicate}); })()`)) return { tabs: count, direction: shift ? 'backward' : 'forward' };
        if (await evaluate(target, `document.activeElement === null || document.activeElement === document.body || document.activeElement.matches('main h1')`)) break;
      }
    }
    throw new Error(`Trusted Tab did not reach ${label}`);
  };
  // Bounded observable settle: poll until two consecutive equal readings, never beyond the original fixed wait.
  const settle = async (expr, budgetMs) => {
    let previous = await evaluate(target, expr); let waited = 0;
    while (waited < budgetMs) {
      await delay(50); waited += 50;
      const next = await evaluate(target, expr);
      if (next === previous && waited >= 100) return next;
      previous = next;
    }
    return previous;
  };
  const shot = async (o, clipExpr, viewport) => {
    const round = (v) => Math.round(v * 1000) / 1000;
    let clip = null; let elementRect = null;
    if (clipExpr) {
      const r = await rect(clipExpr);
      // The exact integral clip is both sent and recorded; the raw rect is reference data only, never a pixel prediction.
      if (r) { elementRect = { left: round(r.left), top: round(r.top), width: round(r.width), height: round(r.height) }; clip = snapClip(r, viewport); }
      if (!clip) throw new Error(`${screenshotName(o)}: element is not in the viewport`);
    }
    const { data } = await call('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false, ...(clip ? { clip } : {}) });
    const png = Buffer.from(data, 'base64');
    if (png.length > MAX_RESPONSIVE_PNG_BYTES) throw new Error(`${screenshotName(o)} exceeds ${MAX_RESPONSIVE_PNG_BYTES} bytes`);
    const dims = pngDimensions(png);
    await fs.writeFile(join(root, screenshotName(o)), png);
    return { name: screenshotName(o), bytes: png.length, sha256: sha256(png), ...dims, clip: clip ? { ...clip } : null, elementRect,
      viewport: { scrollX: viewport.scrollX, scrollY: viewport.scrollY, innerWidth: viewport.innerWidth, innerHeight: viewport.innerHeight, devicePixelRatio: viewport.devicePixelRatio } };
  };
  let phase = 'setup';
  const phaseStart = () => requests.length;
  const phaseLedger = (start) => { const slice = requests.slice(start); for (const entry of slice) entry.ledgered = true; return ledgerSummary(slice); };
  try {
    // A thunk keeps generator failures inside the recorded, partial-evidence path.
    if (typeof fixtures === 'function') fixtures = fixtures();
    section.fixtures = fixtures.identity;
    target = await makeTarget();
    await call('Emulation.setFocusEmulationEnabled', { enabled: true });
    await call('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'reduce' }] });
    fetchHandler = (event) => {
      let url; try { url = new URL(event.request.url); } catch { url = null; }
      const path = url ? url.pathname + url.search : String(event.request.url);
      const accept = Object.entries(event.request.headers ?? {}).find(([name]) => name.toLowerCase() === 'accept')?.[1] ?? '';
      const response = url ? fixtures.respond(event.request.method, path, accept) : { status: 404, document: { kind: 'error' } };
      const unmapped = response.status === 404 || response.status === 400;
      if (unmapped && section.unmapped.length < 32) section.unmapped.push(cap(`${phase} ${event.request.method} ${path}`));
      if (requests.length < MAX_RUN_REQUESTS) requests.push({ phase, method: String(event.request.method), path, status: response.status, unmapped });
      else dropped++;
      if (response.artifact) served.push({ path: url.pathname, ...response.artifact });
      const body = response.bytes ?? Buffer.from(JSON.stringify(response.document));
      const headers = [{ name: 'Content-Type', value: response.contentType ?? 'application/json; charset=utf-8' },
        { name: 'X-Request-ID', value: response.document?.requestId ?? 'request_responsive_artifact' }, { name: 'Cache-Control', value: 'no-store' },
        ...Object.entries(response.headers ?? {}).map(([name, value]) => ({ name, value }))];
      // A failed fulfilment is recorded evidence, never swallowed into an unrelated later timeout.
      const recordPhase = phase;
      const fulfilment = Promise.resolve().then(() => cdp.call('Fetch.fulfillRequest', { requestId: event.requestId, responseCode: response.status, body: body.toString('base64'), responseHeaders: headers }, target.sessionId))
        .catch((error) => { if (section.fulfillFailures.length < 32) section.fulfillFailures.push(cap(`${recordPhase} ${path}: ${String(error?.message ?? error)}`)); });
      pending.add(fulfilment);
      void fulfilment.finally(() => pending.delete(fulfilment));
    };
    cdp.on('Fetch.requestPaused', fetchHandler, target.sessionId);
    await call('Fetch.enable', { patterns: [{ urlPattern: `${origin}/nested/api/v1/*`, requestStage: 'Request' }] });

    for (const profile of profiles) {
      await sizeProfile(profile, call, target);
      const base = { profile: profile.key, profileName: profile.name, sizing };

      // Display preferences disclosure: trusted Tab to the trigger, Enter opens, Tab enters, Escape closes and returns focus.
      phase = `${profile.key}/preferences/disclosure`; let ledgerStart = phaseStart();
      await navigate(NAVIGATION_PAGE.path, `responsive job at ${profile.name}`);
      const longNameRendered = await evaluate(target, `document.body.innerText.includes(${JSON.stringify(fixtures.identity.longName)})`);
      await input();
      const reach = await tabUntil('f.trigger', 'Display preferences');
      await press('Enter'); await delay(150);
      const opened = await evaluate(target, `(() => { const t = document.querySelector('${PREFERENCES.trigger}'); const p = document.getElementById('${PREFERENCES.panel}');
        const r = p?.getBoundingClientRect(); return { expanded: t?.getAttribute('aria-expanded'), panelShown: !!p && p.checkVisibility(),
        panelWithinWidth: !!r && r.left >= -1 && r.right <= document.scrollingElement.clientWidth + 1 }; })()`);
      const page = await evaluate(target, PAGE);
      const prefsShot = await shot({ ...base, kind: 'preferences', subject: 'disclosure' }, `document.getElementById('${PREFERENCES.panel}')`, page);
      await press('Tab'); const inside = await evaluate(target, FOCUS);
      await press('Escape'); await delay(100);
      const closed = { expanded: await evaluate(target, `document.querySelector('${PREFERENCES.trigger}')?.getAttribute('aria-expanded')`), focus: await evaluate(target, FOCUS) };
      section.observations.push({ ...base, kind: 'preferences', subject: 'disclosure', reach, opened, inside, closed, page, longNameRendered,
        input: await input(), screenshot: prefsShot, requests: phaseLedger(ledgerStart) });
      if (!profile.narrow) continue;

      // Navigation disclosure: keyboard open/Tab/Escape/focus return, then touch open and route to heading focus.
      phase = `${profile.key}/navigation/disclosure`; ledgerStart = phaseStart();
      await navigate(NAVIGATION_PAGE.path, `responsive job for navigation at ${profile.name}`);
      await input();
      const navReach = await tabUntil('f.toggle', 'Navigation');
      await press('Enter'); await delay(150);
      const navState = `({ expanded: document.querySelector('.navigation-toggle')?.getAttribute('aria-expanded'), linksShown: !!document.querySelector('#main-navigation-links')?.checkVisibility(),
        overflow: document.scrollingElement.scrollWidth - document.scrollingElement.clientWidth })`;
      const keyboardOpen = await evaluate(target, navState);
      const navPage = await evaluate(target, PAGE);
      const navShot = await shot({ ...base, kind: 'navigation', subject: 'disclosure' }, `document.querySelector('#main-navigation-links')`, navPage);
      await press('Tab'); const linkFocus = await evaluate(target, FOCUS);
      await press('Escape'); await delay(100);
      const escaped = { ...await evaluate(target, navState), focus: await evaluate(target, FOCUS) };
      const keyboardInput = await input();
      await evaluate(target, visible(`document.querySelector('.navigation-toggle')`));
      await tap(await rect(`document.querySelector('.navigation-toggle')`)); await delay(250);
      const touchOpen = await evaluate(target, navState);
      const link = `[...document.querySelectorAll('#main-navigation-links a')].find(a => a.pathname === ${JSON.stringify(NAVIGATION_PAGE.routeLink)})`;
      await evaluate(target, visible(link)); await delay(100);
      await tap(await rect(link));
      await ready(target, `location.pathname === ${JSON.stringify(NAVIGATION_PAGE.routeLink)} && document.activeElement?.matches('main h1')`, `touch route at ${profile.name}`).catch(() => false);
      const routed = { ...await evaluate(target, PAGE), ...await evaluate(target, navState), focus: await evaluate(target, FOCUS) };
      section.observations.push({ ...base, kind: 'navigation', subject: 'disclosure', reach: navReach, keyboardOpen, linkFocus, escaped, touchOpen, routed,
        input: { keyboard: keyboardInput, touch: await input() }, screenshot: navShot, requests: phaseLedger(ledgerStart) });

      // Named regions: trusted ArrowRight, emulated touch drag and tap; the document must not move.
      for (const region of RESPONSIVE_REGIONS) {
        phase = `${profile.key}/region/${region.key}`; ledgerStart = phaseStart();
        const servedStart = served.length;
        await navigate(region.path, `${region.key} at ${profile.name}`);
        for (const step of region.steps) {
          await ready(target, `!!${byLabel(step)}`, `${region.key}: ${step}`);
          await evaluate(target, visible(byLabel(step))); await delay(50);
          await click(await rect(byLabel(step)));
        }
        await ready(target, `!!${regionExpr(region.region)} && !document.querySelector('main [aria-busy="true"]')`, `${region.key} region`);
        const sel = regionExpr(region.region);
        await input();
        // Byte previews live in closed <details>: open the first one by trusted input BEFORE any visibility/width/scroll measure.
        let activation = null;
        if (region.bytePreview) {
          await evaluate(target, visible(summaryExpr(sel))); await delay(50);
          await click(await rect(summaryExpr(sel)));
          await ready(target, `(() => { const s = ${summaryExpr(sel)}; return !!s && s.parentElement.open === true; })()`, `${region.key} byte preview`).catch(() => false);
          activation = { input: await input(), preview: await evaluate(target, bytePreviewExpr(sel)) };
        }
        const reached = await tabUntil(`f.name === ${JSON.stringify(region.region)}`, region.region, 'forward');
        const focus = await evaluate(target, FOCUS);
        const geometry = await evaluate(target, `(() => { const e = ${sel}; return { scrollWidth: e.scrollWidth, clientWidth: e.clientWidth,
          rtl: /[\\u0590-\\u06ff]/u.test(e.textContent) }; })()`);
        if (region.bytePreview) geometry.preview = await evaluate(target, bytePreviewExpr(sel));
        if (region.hexRows) {
          const rows = await evaluate(target, hexRowsExpr(sel));
          geometry.hex = { rows: rows.rows, inside: rows.inside, textLength: rows.text.length, textSha256: sha256(Buffer.from(rows.text, 'utf8')) };
        }
        await evaluate(target, `${sel}.scrollLeft = 0`);
        const before = { ...await evaluate(target, PAGE), regionScrollLeft: 0 };
        for (let i = 0; i < 8; i++) await press('ArrowRight');
        const afterKeys = { ...await evaluate(target, PAGE), regionScrollLeft: await settle(`${sel}.scrollLeft`, 200) };
        const keyboardInput = await input();
        const regionShot = await shot({ ...base, kind: 'region', subject: region.key }, sel, afterKeys);
        await evaluate(target, `(${sel}.scrollLeft = 0, ${sel}.scrollIntoView({ block: 'start', inline: 'nearest' }), true)`); await delay(100);
        const r = await rect(sel);
        const y = Math.min(r.top + 24, (await evaluate(target, 'innerHeight')) - 8);
        const startX = Math.min(r.left + r.width - 16, before.innerWidth - 16);
        const beforeDrag = await evaluate(target, PAGE);
        await call('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: startX, y }] });
        for (let i = 1; i <= 10; i++) { await call('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: Math.max(startX - i * 20, 2), y }] }); await delay(16); }
        await call('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
        const dragScroll = await settle(`${sel}.scrollLeft`, 1200);
        const afterDrag = { ...await evaluate(target, PAGE), regionScrollLeft: dragScroll };
        let tapped = null;
        if (region.tap) {
          const button = `[...${sel}.querySelectorAll('button')].find(b => b.textContent.startsWith(${JSON.stringify(region.tap)}))`;
          await evaluate(target, `(${sel}.scrollLeft = ${sel}.scrollWidth, true)`);
          await evaluate(target, visible(button)); await delay(300);
          await input();
          await tap(await rect(button)); await delay(400);
          tapped = { pressed: await evaluate(target, `${button}?.getAttribute('aria-pressed')`), input: await input() };
        }
        section.observations.push({ ...base, kind: 'region', subject: region.key, region: region.region, mode: region.mode, activation, reached, focus, geometry, before, afterKeys,
          beforeDrag, afterDrag, tapped, input: { keyboard: keyboardInput }, artifacts: served.slice(servedStart), screenshot: regionShot, requests: phaseLedger(ledgerStart) });
      }
    }

    // Real-client digest control, once: the same artifact read renders when exact (positive), and one altered
    // byte is refused with the product's case-refusal copy (tamper). Its reads are ledgered separately.
    const control = RESPONSIVE_REGIONS[0];
    const contentPath = [...fixtures.artifacts.entries()].find(([, value]) => value.kind === control.artifact)[0];
    await sizeControl(call, target);
    const alerts = `[...document.querySelectorAll('main [role="alert"]')].map(e => e.textContent.trim().slice(0, 240))`;
    const runControl = async (label) => {
      phase = `digest/${label}`;
      const start = phaseStart(); const servedStart = served.length; const unmappedStart = section.unmapped.length;
      await navigate(control.path, `digest control (${label})`);
      for (const step of control.steps) {
        await ready(target, `!!${byLabel(step)} || !!document.querySelector('main [role="alert"]')`, `digest control ${label}: ${step}`);
        if (!await evaluate(target, `!!${byLabel(step)}`)) break;
        await evaluate(target, visible(byLabel(step)));
        await click(await rect(byLabel(step)));
      }
      await ready(target, `!!document.querySelector('main [role="alert"]') || !!${regionExpr(control.region)}`, `digest control ${label} outcome`).catch(() => false);
      return { served: served.slice(servedStart), alerts: await evaluate(target, alerts), tableRendered: await evaluate(target, `!!${regionExpr(control.region)}`),
        unmapped: section.unmapped.slice(unmappedStart), requests: phaseLedger(start) };
    };
    const positive = await runControl('positive');
    fixtures.tamper.path = contentPath;
    let tampered;
    try { tampered = await runControl('tamper'); } finally { fixtures.tamper.path = null; }
    section.digestControl = { path: cap(contentPath), kind: control.artifact, expectedSha256: fixtures.artifacts.get(contentPath).sha256,
      expectedBytes: fixtures.artifacts.get(contentPath).sizeBytes, positive, tampered };
    phase = 'teardown';
  } catch (error) {
    failed = true;
    section.failure = cap(String(error?.message ?? error));
    throw error;
  } finally {
    phase = 'teardown';
    if (target) {
      try {
        // Settle in-flight fulfilments while interception is still recorded, then disable; the handler stays
        // attached until Fetch.disable so no paused teardown request goes unrecorded.
        await settleFulfilments();
        await call('Fetch.disable');
        if (fetchHandler) cdp.off?.('Fetch.requestPaused', fetchHandler, target.sessionId);
        await call('Emulation.setTouchEmulationEnabled', { enabled: false });
        if (restoreMetrics) await call('Emulation.clearDeviceMetricsOverride');
        await evaluate(target, `(document.activeElement?.blur?.(), true)`);
        section.restored = { touch: false, metricsCleared: restoreMetrics ? true : 'never-overridden', focus: await evaluate(target, `document.activeElement === document.body || document.activeElement === null`) };
        await cdp.call('Target.closeTarget', { targetId: target.targetId });
      } catch (restoreError) {
        section.restored = null;
        section.restoreFailure = cap(String(restoreError?.message ?? restoreError));
        if (!failed) throw restoreError;
      } finally {
        // Gates run on the returned section: late fulfilment failures and every request are recorded first.
        try {
          if (fetchHandler) cdp.off?.('Fetch.requestPaused', fetchHandler, target.sessionId);
        } catch (detachError) {
          section.restored = null;
          section.restoreFailure ??= cap(String(detachError?.message ?? detachError));
        }
        await settleFulfilments();
        const all = ledgerSummary(requests); const outside = requests.filter((entry) => !entry.ledgered);
        section.requests = { ...all, dropped, truncated: all.truncated || dropped > 0,
          unledgered: { ...ledgerSummary(outside), phases: [...new Set(outside.map((entry) => entry.phase))].slice(0, 32) } };
      }
    }
  }
  return section;
}

/** PNG signature and IHDR dimensions; throws on anything else. */
export function pngDimensions(bytes) {
  const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  if (!Buffer.isBuffer(bytes) || bytes.length < 33 || !bytes.subarray(0, 8).equals(signature) || bytes.toString('latin1', 12, 16) !== 'IHDR')
    throw new Error('not a PNG image');
  const width = bytes.readUInt32BE(16); const height = bytes.readUInt32BE(20);
  if (width === 0 || height === 0) throw new Error('empty PNG image');
  return { width, height };
}

const trusted = (events, type, filter = () => true) => Array.isArray(events) && events.some((e) => e?.type === type && e.trusted === true && filter(e));
const untrusted = (events) => !Array.isArray(events) || events.some((e) => e?.trusted !== true);
const fixed = (a, b) => !!a && !!b && a.scrollX === 0 && b.scrollX === 0 && Math.abs((a.scrollY ?? NaN) - (b.scrollY ?? NaN)) <= 1 && b.overflow <= 1;
const finite = (...values) => values.every((v) => typeof v === 'number' && Number.isFinite(v));

/** PNG bound to its actual integral clip and the device profile: pixels = clip CSS size x DPR exactly, clip inside the viewport. */
function screenshotFailure(s, profile) {
  const c = s.clip; const v = s.viewport;
  if (!c || !v || !finite(c.x, c.y, c.width, c.height, v.scrollX, v.scrollY) || c.scale !== 1) return 'screenshot is not a bounded element clip within the viewport';
  if (v.innerWidth !== profile.width || v.innerHeight !== profile.height || v.devicePixelRatio !== profile.deviceScaleFactor) return 'screenshot viewport differs from the device profile';
  if (![c.x, c.y, c.width, c.height, v.scrollX, v.scrollY, profile.deviceScaleFactor].every(Number.isInteger)) return 'screenshot clip is not integral CSS pixels';
  if (c.width < 1 || c.height < 1 || c.x < v.scrollX || c.y < v.scrollY || c.x + c.width > v.scrollX + v.innerWidth || c.y + c.height > v.scrollY + v.innerHeight)
    return 'screenshot is not a bounded element clip within the viewport';
  const dpr = profile.deviceScaleFactor;
  if (s.width !== c.width * dpr || s.height !== c.height * dpr)
    return `screenshot ${s.width}x${s.height} is not its clip ${c.width}x${c.height} at ${dpr}x`;
  return null;
}

/** Bounded per-phase request ledger: no failed/unmapped reads, no mutations, no retry storm, exact reads where stable. */
function ledgerFailures(ledger, exact = []) {
  const out = [];
  if (!ledger || !Array.isArray(ledger.paths) || ledger.truncated !== false) return ['request ledger missing or truncated'];
  if (ledger.failed !== 0) out.push(`${ledger.failed} failed or unmapped API reads ${cap(JSON.stringify(ledger.paths.filter((p) => p.status >= 400).map((p) => [p.path, p.status])))}`);
  if (ledger.mutations !== 0) out.push(`${ledger.mutations} API mutations during a read-only audit`);
  if (!(ledger.reads >= 1 && ledger.reads <= MAX_PHASE_READS)) out.push(`${ledger.reads} API reads outside 1..${MAX_PHASE_READS}`);
  const sum = ledger.paths.reduce((n, p) => n + p.count, 0);
  if (sum !== ledger.reads + ledger.mutations) out.push('request ledger totals are inconsistent');
  const counts = new Map();
  for (const p of ledger.paths) counts.set(p.path, (counts.get(p.path) ?? 0) + p.count);
  for (const [path, count] of counts) if (count > MAX_SAME_PATH_READS) out.push(`retry storm: ${cap(path)} read ${count} times`);
  for (const { path, count } of exact) if ((counts.get(path) ?? 0) !== count) out.push(`expected exactly ${count} read(s) of ${cap(path)}, found ${counts.get(path) ?? 0}`);
  return out;
}

/** Whole-run ledger: setup, teardown and between-phase requests included; nothing dropped, failed, mutating or storming. */
export function runLedgerFailures(l) {
  if (!l || typeof l !== 'object' || !Array.isArray(l.paths) || !l.unledgered || !Array.isArray(l.unledgered.paths)) return ['run request ledger missing'];
  const out = [];
  if (!(Number.isInteger(l.dropped) && l.dropped === 0)) out.push(`run request ledger truncated (${cap(String(l.dropped))} dropped beyond ${MAX_RUN_REQUESTS})`);
  else if (l.truncated !== false) out.push(`run request ledger exceeds ${LEDGER_CAP} distinct request keys`);
  if (l.failed !== 0) out.push(`run: ${l.failed} failed or unmapped API reads`);
  if (l.mutations !== 0) out.push(`run: ${l.mutations} API mutations during a read-only audit`);
  if (!(Number.isInteger(l.reads) && Number.isInteger(l.mutations) && l.reads + l.mutations <= MAX_RUN_REQUESTS)) out.push('run request ledger totals are out of bounds');
  const u = l.unledgered; const where = cap(JSON.stringify(u.phases ?? null));
  if (u.failed !== 0) out.push(`outside observation phases ${where}: ${u.failed} failed or unmapped API reads`);
  if (u.mutations !== 0) out.push(`outside observation phases ${where}: ${u.mutations} API mutations`);
  if (u.truncated !== false) out.push('outside-phase request ledger truncated');
  const counts = new Map();
  for (const p of u.paths) counts.set(p.path, (counts.get(p.path) ?? 0) + p.count);
  for (const [path, count] of counts) if (count > MAX_SAME_PATH_READS) out.push(`retry storm outside observation phases: ${cap(path)} read ${count} times`);
  return out;
}

/** Semantic failures for one observation. */
export function assessResponsiveObservation(o, expected, identity, regions = RESPONSIVE_REGIONS, options = {}) {
  const failures = [];
  const where = `${expected.profile}/${expected.kind}/${expected.subject}`;
  const fail = (message) => failures.push(`${where}: ${message}`);
  const profile = options.profile ?? RESPONSIVE_PROFILES.find((p) => p.key === expected.profile);
  if (o.profileName !== profile.name || o.sizing !== (options.sizing ?? RESPONSIVE_SIZING)) fail('profile identity or sizing label differs');
  const s = o.screenshot ?? {};
  const page = o.page ?? o.afterKeys ?? o.routed;
  if (s.name !== screenshotName(expected) || !HEX64.test(s.sha256 ?? '') || !(s.bytes > 0 && s.bytes <= MAX_RESPONSIVE_PNG_BYTES)) fail('bounded screenshot evidence missing');
  else { const problem = (options.screenshotFailure ?? screenshotFailure)(s, profile); if (problem) fail(problem); }
  if (options.pageFailure) { for (const [label, value] of [['page', page], ['before', o.before], ['afterDrag', o.afterDrag], ['routed', o.routed]]) {
    const problem = value ? options.pageFailure(value) : null; if (problem) fail(`${label}: ${problem}`); } }
  else if (page && (page.innerWidth !== profile.width || page.devicePixelRatio !== profile.deviceScaleFactor)) fail(`observed ${page.innerWidth}px @${page.devicePixelRatio}x differs from the profile`);
  const region = expected.kind === 'region' ? regions.find((r) => r.key === expected.subject) : null;
  const artifactPath = region?.artifact ? identity?.artifactPaths?.[region.artifact] : null;
  const exact = [...(artifactPath ? [{ path: artifactPath, count: 1 }] : []), ...(region?.hexRows && identity?.hex?.chunkPath ? [{ path: identity.hex.chunkPath, count: 1 }] : [])];
  for (const problem of ledgerFailures(o.requests, exact)) fail(problem);
  if (expected.kind === 'preferences') {
    if (o.longNameRendered !== true) fail('long RTL/CJK/emoji job name was not rendered');
    if (!(o.reach?.tabs >= 1 && o.reach.tabs <= MAX_TABS)) fail('trigger not reached by trusted Tab');
    if (o.opened?.expanded !== 'true' || o.opened?.panelShown !== true || o.opened?.panelWithinWidth !== true) fail(`disclosure did not open within the viewport ${JSON.stringify(o.opened ?? null)}`);
    if (o.inside?.inPreferences !== true || o.inside?.focusVisible !== true) fail('Tab did not move visible focus into the disclosure panel');
    if (o.closed?.expanded !== 'false' || o.closed?.focus?.trigger !== true || o.closed?.focus?.focusVisible !== true) fail('Escape did not close the disclosure and return visible focus to its trigger');
    if (untrusted(o.input) || !trusted(o.input, 'keydown', (e) => e.key === 'Enter') || !trusted(o.input, 'keydown', (e) => e.key === 'Escape')) fail('disclosure input was not trusted Enter/Escape');
  } else if (expected.kind === 'navigation') {
    if (!(o.reach?.tabs >= 1 && o.reach.tabs <= MAX_TABS)) fail('Navigation not reached by trusted Tab');
    if (o.keyboardOpen?.expanded !== 'true' || o.keyboardOpen?.linksShown !== true || !(o.keyboardOpen?.overflow <= 1)) fail('Enter did not open the disclosure without page overflow');
    if (o.linkFocus?.inNavigation !== true || o.linkFocus?.focusVisible !== true) fail('Tab did not move visible focus to a navigation link');
    if (o.escaped?.expanded !== 'false' || o.escaped?.linksShown !== false || o.escaped?.focus?.toggle !== true || o.escaped?.focus?.focusVisible !== true)
      fail('Escape did not close and return visible focus to Navigation');
    if (o.touchOpen?.expanded !== 'true' || o.touchOpen?.linksShown !== true) fail('touch tap did not open the disclosure');
    if (o.routed?.path !== NAVIGATION_PAGE.routeLink || o.routed?.expanded !== 'false' || o.routed?.focus?.heading !== true || o.routed?.h1 !== NAVIGATION_PAGE.routeHeading)
      fail(`touch route did not close the disclosure and focus the route heading ${JSON.stringify(o.routed ?? null)}`);
    const k = o.input?.keyboard; const t = o.input?.touch;
    if (untrusted(k) || !['Tab', 'Enter', 'Escape'].every((key) => trusted(k, 'keydown', (e) => e.key === key))) fail('navigation keyboard input was not trusted Tab/Enter/Escape');
    if (untrusted(t) || !trusted(t, 'touchstart') || !trusted(t, 'pointerdown', (e) => e.pointerType === 'touch') || !trusted(t, 'click')) fail('navigation touch input was not trusted touch/pointer/click');
  } else {
    if (o.region !== region.region || o.mode !== region.mode || o.focus?.name !== region.region || o.focus?.focusVisible !== true) fail('named region did not receive visible trusted focus');
    if (!(o.reached?.tabs >= 1 && o.reached.tabs <= MAX_TABS)) fail('region not reached by trusted Tab');
    if (region.bytePreview) {
      const a = o.activation; const p = o.geometry?.preview;
      if (!a || untrusted(a.input) || !trusted(a.input, 'click', (e) => e.target === 'summary') || a.preview?.open !== true)
        fail('byte preview disclosure was not opened by trusted activation before measurement');
      if (!p || p.open !== true || !PRODUCT_COPY.previewTitles.includes(p.summary) || !(p.visible >= 1) || !(p.rem > 0 && p.minWidth >= 16 * p.rem - 1))
        fail(`byte preview not visibly rendered at its minimum width in the region ${cap(JSON.stringify(p ?? null))}`);
    } else if (o.activation !== null && o.activation !== undefined) fail('unexpected activation in a region without byte previews');
    if (region.artifact && o.geometry?.rtl !== true) fail('long RTL case identity not rendered');
    const keys = o.input?.keyboard;
    if (untrusted(keys) || (keys.filter((e) => e.type === 'keydown' && e.key === 'ArrowRight').length !== 8)) fail('region keys were not eight trusted ArrowRight presses');
    if (!fixed(o.before, o.afterKeys)) fail('document moved during keyboard scrolling');
    if (!fixed(o.beforeDrag, o.afterDrag)) fail('document moved during touch drag');
    if (region.mode === 'scroll') {
      if (!(o.geometry?.scrollWidth > o.geometry?.clientWidth + 1)) fail('region content does not overflow (insufficient fixture)');
      if (!(o.afterKeys?.regionScrollLeft >= 16)) fail(`ArrowRight did not scroll the region (${o.afterKeys?.regionScrollLeft})`);
      if (!(o.afterDrag?.regionScrollLeft >= 24)) fail(`touch drag did not scroll the region (${o.afterDrag?.regionScrollLeft})`);
    } else {
      const g = o.geometry ?? {}; const h = g.hex ?? {}; const want = identity?.hex ?? {};
      if (!(finite(g.scrollWidth, g.clientWidth) && g.scrollWidth <= g.clientWidth + 1)) fail(`reflow region overflows (${g.scrollWidth} > ${g.clientWidth})`);
      if (!(want.rows >= 1) || h.rows !== want.rows || h.inside !== want.rows) fail(`reflowed rows not all inside the region (${h.inside}/${h.rows} of ${want.rows})`);
      if (!HEX64.test(h.textSha256 ?? '') || h.textSha256 !== want.textSha256) fail('rendered hex rows differ from the exact requested fixture bytes');
      if (o.afterKeys?.regionScrollLeft !== 0 || o.afterDrag?.regionScrollLeft !== 0) fail('reflow region scrolled horizontally (hidden overflow)');
    }
    if (region.tap && (o.tapped?.pressed !== 'true' || untrusted(o.tapped?.input) || !trusted(o.tapped?.input, 'touchstart') || !trusted(o.tapped?.input, 'click')))
      fail('touch tap did not activate the in-region action with trusted input');
    if (region.artifact) {
      const bound = identity?.artifacts?.find((a) => a.kind === region.artifact);
      const raw = Array.isArray(o.artifacts) ? o.artifacts : [];
      if (!bound || raw.length !== 1 || raw[0]?.kind !== region.artifact || raw[0].servedSha256 !== bound.sha256 || raw[0].servedBytes !== bound.sizeBytes)
        fail('raw artifact bytes were not served exactly once at the bound size/sha256');
    } else if (Array.isArray(o.artifacts) && o.artifacts.length) fail('unexpected raw artifact reads');
  }
  return failures;
}

/** Digest control: positive exact read renders; tampered read of the same single artifact is refused with product copy only. */
export function digestFailures(d, f) {
  const out = [];
  const bound = f.artifacts?.find?.((a) => a?.kind === d?.kind && a.sha256 === d?.expectedSha256 && a.sizeBytes === d?.expectedBytes);
  if (!bound || d.kind !== RESPONSIVE_REGIONS[0].artifact) return ['real-client digest control missing or not bound to the fixture artifact'];
  const path = f.artifactPaths?.[d.kind];
  const one = (run) => Array.isArray(run?.served) && run.served.length === 1 && run.served[0].kind === d.kind && run.served[0].servedBytes === d.expectedBytes;
  const p = d.positive; const t = d.tampered;
  if (!one(p) || p.served[0].servedSha256 !== d.expectedSha256 || p.tableRendered !== true || !Array.isArray(p.alerts) || p.alerts.length !== 0)
    out.push('digest control positive: the exact artifact was not rendered without alerts');
  if (!one(t) || t.served[0].servedSha256 === d.expectedSha256 || !HEX64.test(t.served[0].servedSha256 ?? ''))
    out.push('digest control tamper: not exactly one altered read of the bound artifact');
  if (!Array.isArray(t?.alerts) || t.alerts.length !== 1 || t.alerts[0] !== PRODUCT_COPY.caseRefusal || t.tableRendered !== false)
    out.push(`digest control tamper: refusal was not the product case-refusal copy alone ${cap(JSON.stringify(t?.alerts ?? null))}`);
  for (const [label, run] of [['positive', p], ['tamper', t]]) {
    if (!Array.isArray(run?.unmapped) || run.unmapped.length !== 0) out.push(`digest control ${label}: unmapped reads`);
    for (const problem of ledgerFailures(run?.requests, path ? [{ path, count: 1 }] : [{ path: '(artifact path unbound)', count: 1 }])) out.push(`digest control ${label}: ${problem}`);
  }
  return out;
}

/** Semantic gate over report.auditResponsive; format integrity stays the report loader's job. */
export function assessResponsiveReport(section) {
  if (!section || typeof section !== 'object') return ['auditResponsive evidence missing (report predates #619 responsive coverage)'];
  const failures = [];
  if (section.schema !== RESPONSIVE_SCHEMA) failures.push(`auditResponsive schema ${JSON.stringify(section.schema ?? null)}`);
  if (section.sizing !== RESPONSIVE_SIZING || section.touch !== RESPONSIVE_TOUCH) failures.push('sizing/touch provenance labels changed');
  const f = section.fixtures ?? {};
  failures.push(...fixtureFailures(f));
  const observations = Array.isArray(section.observations) ? section.observations : [];
  const matrix = expectedObservations();
  if (observations.length !== matrix.length) failures.push(`expected ${matrix.length} observations, found ${observations.length}`);
  for (const expected of matrix) {
    const matches = observations.filter((o) => o?.profile === expected.profile && o?.kind === expected.kind && o?.subject === expected.subject);
    if (matches.length !== 1) failures.push(`${expected.profile}/${expected.kind}/${expected.subject}: expected one observation, found ${matches.length}`);
    else failures.push(...assessResponsiveObservation(matches[0], expected, f));
  }
  for (const o of observations) if (!matrix.some((e) => e.profile === o?.profile && e.kind === o?.kind && e.subject === o?.subject)) failures.push(`unexpected observation ${cap(JSON.stringify([o?.profile, o?.kind, o?.subject]))}`);
  const names = observations.map((o) => o?.screenshot?.name);
  if (new Set(names).size !== names.length) failures.push('screenshot names are not distinct');
  failures.push(...digestFailures(section.digestControl ?? {}, f));
  // Every 400/404 read is unmapped evidence loss; none is allowlisted.
  if (!Array.isArray(section.unmapped)) failures.push('unmapped read record missing');
  else if (section.unmapped.length) failures.push(`unmapped API reads: ${cap(section.unmapped.slice(0, 4).join(', '))}`);
  if (!Array.isArray(section.fulfillFailures)) failures.push('fulfilment failure record missing');
  else if (section.fulfillFailures.length) failures.push(`Fetch.fulfillRequest failed: ${cap(section.fulfillFailures.slice(0, 2).join(', '))}`);
  failures.push(...runLedgerFailures(section.requests));
  if (section.failure !== undefined) failures.push(`responsive driver failed: ${cap(String(section.failure))}`);
  if (section.restoreFailure !== undefined) failures.push(`state restoration failed: ${cap(String(section.restoreFailure))}`);
  if (section.restored?.touch !== false || section.restored?.metricsCleared !== true || section.restored?.focus !== true) failures.push('viewport/touch/focus state was not restored');
  return failures;
}

/** Fixture generator identity and #619 scenario bindings (shared by the v2 gate and the real-zoom gate). */
export function fixtureFailures(f) {
  const failures = [];
  if (f.generator !== 'frontend/dev/generate-fixtures.py' || !HEX64.test(f.generatorSha256 ?? '') || !HEX64.test(f.outputSha256 ?? '') || !HEX64.test(f.schemaSha256 ?? '')) failures.push('fixture generator identity missing');
  if (f.jobId !== RESPONSIVE_JOB || f.runId !== RESPONSIVE_RUN || f.revisionId !== RESPONSIVE_REVISION
    || JSON.stringify(f.explorationRuns) !== JSON.stringify(RESPONSIVE_EXPLORATION.map((k) => `${RESPONSIVE_RUN}_${k}`))) failures.push('fixture identities differ from the #619 scenario');
  for (const [name, pattern] of Object.entries(LONG_NAME_CLASSES)) if (typeof f.longName !== 'string' || !pattern.test(f.longName)) failures.push(`long name lacks ${name} text`);
  if (!(typeof f.longName === 'string' && f.longName.length >= 160)) failures.push('long name is not long');
  if (!Array.isArray(f.artifacts) || RESPONSIVE_EXPLORATION.some((kind) => f.artifacts.filter((a) => a?.kind === kind && a.sizeBytes > 0 && HEX64.test(a.sha256 ?? '')).length !== 1)
    || RESPONSIVE_EXPLORATION.some((kind) => typeof f.artifactPaths?.[kind] !== 'string'))
    failures.push('bound exploration artifacts missing');
  if (!(f.hex?.rows >= 1) || !HEX64.test(f.hex?.textSha256 ?? '') || typeof f.hex?.chunkPath !== 'string' || !(f.hex?.hexChars >= 1024)) failures.push('bound hex source chunk missing');
  return failures;
}

/** Bounded, no-symlink regular-file read of one fixed-name PNG; returns size, sha256 and IHDR dimensions. */
export async function readResponsivePng(directory, name, { maxBytes = MAX_RESPONSIVE_PNG_BYTES, names = FIXED_NAMES } = {}) {
  if (!names.has(name)) throw new Error(`unexpected screenshot name ${JSON.stringify(cap(String(name)))}`);
  const path = join(directory, name);
  const link = await fs.lstat(path);
  if (link.isSymbolicLink() || !link.isFile()) throw new Error(`${name} is not a regular file`);
  if (link.size > maxBytes) throw new Error(`${name} exceeds ${maxBytes} bytes`);
  const handle = await fs.open(path, fsConstants.O_RDONLY | (fsConstants.O_NOFOLLOW ?? 0));
  try {
    const stat = await handle.stat();
    if (!stat.isFile() || stat.ino !== link.ino || stat.dev !== link.dev || stat.size > maxBytes) throw new Error(`${name} changed while opening`);
    const buffer = Buffer.alloc(maxBytes + 1);
    let length = 0;
    for (;;) {
      const { bytesRead } = await handle.read(buffer, length, buffer.length - length, length);
      if (bytesRead === 0) break;
      length += bytesRead;
      if (length > maxBytes) throw new Error(`${name} exceeds ${maxBytes} bytes`);
    }
    const bytes = buffer.subarray(0, length);
    return { bytes: length, sha256: sha256(bytes), ...pngDimensions(bytes) };
  } finally { await handle.close(); }
}

export async function verifyResponsiveScreenshots(directory, section, { names = FIXED_NAMES } = {}) {
  const failures = [];
  for (const o of section?.observations ?? []) {
    const s = o?.screenshot ?? {};
    try {
      const actual = await readResponsivePng(directory, s.name, { names });
      if (actual.bytes !== s.bytes || actual.sha256 !== s.sha256 || actual.width !== s.width || actual.height !== s.height) failures.push(`${s.name}: retained PNG differs from recorded size/sha256/dimensions`);
    } catch (error) {
      failures.push(`${cap(String(s.name))}: retained PNG invalid (${error?.code === 'ENOENT' ? 'missing' : cap(String(error?.message ?? error))})`);
    }
  }
  return failures;
}

/** Verifier semantic gate: every integrity-verified passed audit report must carry complete responsive evidence. */
export async function applyAuditResponsiveGate(results, load) {
  for (const result of results) {
    if (!result.ok || result.mode !== 'audit' || result.status !== 'passed') continue;
    let failures;
    try {
      const section = (await load(result.directory)).auditResponsive;
      failures = assessResponsiveReport(section);
      if (failures.length === 0) failures = await verifyResponsiveScreenshots(result.directory, section);
    } catch (error) { failures = [`report reload failed: ${cap(String(error?.message ?? error))}`]; }
    result.responsiveGate = failures.length ? 'failed' : 'passed';
    if (failures.length) {
      result.ok = false;
      result.error = `integrity verified; #619 responsive semantic gate failed: ${failures.slice(0, 6).join('; ')}${failures.length > 6 ? ` (+${failures.length - 6} more)` : ''}`;
    }
  }
  return results;
}
